questions.solution:
PROTOCOL_VERSION = "2026-07-28"


def build_call(request_id, tool, arguments, capabilities=None):
    """Return (body, headers) for one tools/call POST over Streamable HTTP."""
    body = {
        "jsonrpc": "2.0",
        "id": request_id,
        "method": "tools/call",
        "params": {
            "name": tool,
            "arguments": arguments,
            "_meta": {
                "io.modelcontextprotocol/protocolVersion": PROTOCOL_VERSION,
                "io.modelcontextprotocol/clientInfo": {"name": "hand-client", "version": "1.0.0"},
                "io.modelcontextprotocol/clientCapabilities": dict(capabilities or {}),
            },
        },
    }
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
        "MCP-Protocol-Version": PROTOCOL_VERSION,
        "Mcp-Method": "tools/call",
        "Mcp-Name": tool,
    }
    return body, headers

questions.tests:
ok = {"jsonrpc": "2.0", "id": 1, "result": {"resultType": "complete", "content": []}}
assert classify(ok) == "complete"

failed = {"jsonrpc": "2.0", "id": 4, "result": {"resultType": "complete", "isError": True,
          "content": [{"type": "text", "text": "Invalid departure date: must be in the future."}]}}
assert classify(failed) == "tool-error", "isError: true is a tool execution error, not a success"

explicit_false = {"jsonrpc": "2.0", "id": 5, "result": {"resultType": "complete", "isError": False, "content": []}}
assert classify(explicit_false) == "complete"

legacy = {"jsonrpc": "2.0", "id": 2, "result": {"tools": []}}
assert classify(legacy) == "complete", "an absent resultType must be treated as complete"

legacy_failed = {"jsonrpc": "2.0", "id": 3, "result": {"isError": True, "content": []}}
assert classify(legacy_failed) == "tool-error"

error = {"jsonrpc": "2.0", "id": 6, "error": {"code": -32602, "message": "Unknown tool: get_wether"}}
assert classify(error) == "protocol-error"

parse = {"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error"}}
assert classify(parse) == "protocol-error"

asking = {"jsonrpc": "2.0", "id": 7, "result": {"resultType": "input_required", "requestState": "opaque"}}
assert classify(asking) == "input-required"

task = {"jsonrpc": "2.0", "id": 8, "result": {"resultType": "task", "taskId": "t-1"}}
assert classify(task) == "invalid", "a value from an extension the client did not advertise is invalid"
assert classify(task, advertised=("task",)) == "task"

odd = {"jsonrpc": "2.0", "id": 9, "result": {"resultType": "partial", "content": []}}
assert classify(odd) == "invalid", "an unrecognized resultType must be treated as invalid"
odd_failed = {"jsonrpc": "2.0", "id": 10, "result": {"resultType": "partial", "isError": True, "content": []}}
assert classify(odd_failed) == "invalid", "isError marks a tool error only on a result recognized as complete"
print("all tests passed")
